import { afterEach, describe, expect, it, vi } from 'vitest';
import type { Order } from '../../../task-a3-unit-tests/src/services/createCouponOrder';
import { createCouponOrder } from '../../../task-a3-unit-tests/src/services/createCouponOrder';
import type { Coupon } from '../../../task-a3-unit-tests/src/domain/coupon';

vi.mock('server-only', () => ({}), { virtual: true });
const { calculateCouponDiscount, validateCouponCode } = await import('../../../task-a3-unit-tests/real/lib/coupons');

type RecordData = { id: string; code: string; name: string; description: null; discount_type: 'percentage' | 'fixed'; discount_value: number; minimum_amount: number; maximum_discount: number | null; usage_limit: number | null; usage_count: number | null; user_usage_limit: number | null; valid_from: string | null; valid_until: string | null; is_active: boolean; applies_to_product_id: string | null };
const record = (changes: Partial<RecordData> = {}): RecordData => ({ id: 'coupon-1', code: 'SAVE', name: 'Save', description: null, discount_type: 'fixed', discount_value: 1000, minimum_amount: 0, maximum_discount: null, usage_limit: null, usage_count: 0, user_usage_limit: 1, valid_from: null, valid_until: null, is_active: true, applies_to_product_id: null, ...changes });
function fakeDb(data: RecordData | null, usageCount = 0) {
  const couponQuery: any = {}; couponQuery.select = vi.fn(() => couponQuery); couponQuery.eq = vi.fn(() => couponQuery); couponQuery.maybeSingle = vi.fn().mockResolvedValue({ data, error: null });
  let n = 0; const usageQuery: any = {}; usageQuery.select = vi.fn(() => usageQuery); usageQuery.eq = vi.fn(() => ++n === 2 ? Promise.resolve({ count: usageCount, error: null }) : usageQuery);
  const from = vi.fn((table: string) => table === 'coupons' ? couponQuery : usageQuery); return { client: { from } as any, from };
}
afterEach(() => { vi.useRealTimers(); vi.restoreAllMocks(); });

describe('A-3 refined requirements', () => {
  it('calculates percentage and fixed discounts without exceeding subtotal', () => {
    expect(calculateCouponDiscount({ discount_type: 'percentage', discount_value: 20, maximum_discount: null }, 10000)).toBe(2000);
    expect(calculateCouponDiscount({ discount_type: 'fixed', discount_value: 15000, maximum_discount: null }, 10000)).toBe(10000);
  });
  it.each([
    ['percentage', 50, 2000, 2000], ['percentage', 50, 0, 0],
    ['fixed', 5000, 2000, 2000], ['fixed', 5000, 0, 0],
  ] as const)('applies maximum_discount for %s coupons', (discount_type, discount_value, maximum_discount, expected) => {
    expect(calculateCouponDiscount({ discount_type, discount_value, maximum_discount }, 10000)).toBe(expected);
  });
  it.each([['   ', 'user-1', 400, '쿠폰 코드를 입력해주세요.'], ['SAVE', '', 401, '로그인이 필요합니다.']] as const)('guards input before DB', async (code, userId, status, error) => {
    const from = vi.fn(); expect(await validateCouponCode({ supabase: { from } as any, code, subtotal: 10000, userId })).toEqual({ error, status }); expect(from).not.toHaveBeenCalled();
  });
  it('rejects missing and expired coupons', async () => {
    expect(await validateCouponCode({ supabase: fakeDb(null).client, code: 'SAVE', subtotal: 10000, userId: 'user-1' })).toEqual({ error: '유효하지 않은 쿠폰 코드입니다.', status: 404 });
    vi.useFakeTimers(); vi.setSystemTime(new Date('2026-08-17T12:00:00+09:00'));
    expect(await validateCouponCode({ supabase: fakeDb(record({ valid_until: '2026-08-16' })).client, code: 'SAVE', subtotal: 10000, userId: 'user-1' })).toEqual({ error: '만료된 쿠폰입니다.', status: 400 });
  });
  it('accepts minimum equality and rejects one won below with fresh fakes', async () => {
    expect(await validateCouponCode({ supabase: fakeDb(record({ minimum_amount: 10000 })).client, code: 'SAVE', subtotal: 10000, userId: 'user-1' })).toMatchObject({ discountAmount: 1000, finalAmount: 9000 });
    expect(await validateCouponCode({ supabase: fakeDb(record({ minimum_amount: 10000 })).client, code: 'SAVE', subtotal: 9999, userId: 'user-1' })).toEqual({ error: '최소 주문 금액 10,000원 이상이어야 합니다.', status: 400 });
  });
  it('rejects a user at user_usage_limit', async () => {
    expect(await validateCouponCode({ supabase: fakeDb(record({ user_usage_limit: 1 }), 1).client, code: 'SAVE', subtotal: 10000, userId: 'user-1' })).toEqual({ error: '이미 사용 한도를 채운 쿠폰입니다.', status: 400 });
  });
  it('uses real domain calculation and strictly typed external fakes', async () => {
    const coupon: Coupon = { code: 'P20', type: 'PERCENTAGE', value: 20, minOrderAmount: 0, expiresAt: new Date('2026-12-31T00:00:00Z'), isActive: true };
    const couponRepository = { findByCode: vi.fn().mockResolvedValue(coupon) }; const paymentGateway = { requestPayment: vi.fn().mockResolvedValue({ approved: true, approvedAmount: 8000 }) }; const orderRepository = { save: vi.fn(async (order: Order): Promise<Order> => order) };
    const order = await createCouponOrder({ orderId: 'order-1', productCode: 'P1', productPrice: 10000, couponCode: 'P20', now: new Date('2026-08-17T00:00:00Z'), couponRepository, paymentGateway, orderRepository });
    expect(paymentGateway.requestPayment).toHaveBeenCalledWith({ orderId: 'order-1', amount: 8000 }); expect(order).toMatchObject({ discountAmount: 2000, finalAmount: 8000, status: 'PAID' });
  });
  it('does not call payment or save for a minimum failure', async () => {
    const coupon: Coupon = { code: 'FIX', type: 'FIXED', value: 1000, minOrderAmount: 10000, expiresAt: new Date('2026-12-31T00:00:00Z'), isActive: true };
    const paymentGateway = { requestPayment: vi.fn() }; const orderRepository = { save: vi.fn() };
    await expect(createCouponOrder({ orderId: 'o2', productCode: 'P1', productPrice: 9999, couponCode: 'FIX', now: new Date('2026-08-17T00:00:00Z'), couponRepository: { findByCode: vi.fn().mockResolvedValue(coupon) }, paymentGateway, orderRepository })).rejects.toThrow('Coupon not applicable: MIN_ORDER_AMOUNT_NOT_MET');
    expect(paymentGateway.requestPayment).not.toHaveBeenCalled(); expect(orderRepository.save).not.toHaveBeenCalled();
  });
});

